package main

const (
	inventoryIdentitySQL                 = "SELECT /*+ MAX_EXECUTION_TIME(5000) */ CONNECTION_ID(), @@server_uuid, DATABASE(), VERSION(), CURRENT_ROLE()"
	inventoryObjectsPresentSQL           = "SELECT /*+ MAX_EXECUTION_TIME(5000) */ TABLE_NAME, TABLE_TYPE, ENGINE FROM information_schema.TABLES WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME IN ('testee','operators','testee_store_migration_manifests','testee_store_migration_items','testee_store_migration_reversions','operator_retirement_manifests','clinician_operator_binding_archive','ai_bridge_requests','ai_bridge_request_assessments') ORDER BY TABLE_NAME LIMIT 1001"
	inventoryTesteeTagsPartitionSQL      = "SELECT /*+ MAX_EXECUTION_TIME(5000) */ COUNT(*) AS total, COALESCE(SUM(tags IS NULL),0) AS sql_null, COALESCE(SUM(tags IS NOT NULL),0) AS non_null, COALESCE(SUM(CASE WHEN JSON_TYPE(tags)='NULL' THEN 1 ELSE 0 END),0) AS json_null, COALESCE(SUM(CASE WHEN JSON_TYPE(tags)='ARRAY' AND JSON_LENGTH(tags)=0 THEN 1 ELSE 0 END),0) AS empty_array, COALESCE(SUM(CASE WHEN JSON_TYPE(tags)='ARRAY' AND JSON_LENGTH(tags)>0 THEN 1 ELSE 0 END),0) AS non_empty_array, COALESCE(SUM(CASE WHEN tags IS NOT NULL AND JSON_TYPE(tags) NOT IN ('NULL','ARRAY') THEN 1 ELSE 0 END),0) AS other FROM testee LIMIT 1001"
	inventoryOperatorsRoleDuplicationSQL = "SELECT /*+ MAX_EXECUTION_TIME(5000) */ COUNT(*) AS total, COALESCE(SUM(roles IS NULL),0) AS roles_sql_null, COALESCE(SUM(effective_roles IS NULL),0) AS effective_sql_null, COALESCE(SUM(CASE WHEN JSON_TYPE(roles)='ARRAY' AND JSON_TYPE(effective_roles)='ARRAY' THEN 1 ELSE 0 END),0) AS both_arrays, COALESCE(SUM(CASE WHEN CAST(roles AS BINARY) <=> CAST(effective_roles AS BINARY) THEN 1 ELSE 0 END),0) AS same_canonical_json_bytes, COALESCE(SUM(CASE WHEN NOT(CAST(roles AS BINARY) <=> CAST(effective_roles AS BINARY)) THEN 1 ELSE 0 END),0) AS different_canonical_json_bytes FROM operators LIMIT 1001"
	inventoryFiveTableCountsSQL          = "SELECT /*+ MAX_EXECUTION_TIME(5000) */ 'testee_store_migration_manifests' AS object_name, COUNT(*) AS total FROM testee_store_migration_manifests UNION ALL SELECT 'testee_store_migration_items', COUNT(*) FROM testee_store_migration_items UNION ALL SELECT 'testee_store_migration_reversions', COUNT(*) FROM testee_store_migration_reversions UNION ALL SELECT 'operator_retirement_manifests', COUNT(*) FROM operator_retirement_manifests UNION ALL SELECT 'clinician_operator_binding_archive', COUNT(*) FROM clinician_operator_binding_archive LIMIT 1001"
	inventoryTesteeManifestStatesSQL     = "SELECT /*+ MAX_EXECUTION_TIME(5000) */ CASE WHEN BINARY state='applied' THEN 'applied' WHEN BINARY state='rolled_back' THEN 'rolled_back' ELSE 'unknown' END AS state_group, COUNT(*) AS total FROM testee_store_migration_manifests GROUP BY state_group ORDER BY state_group LIMIT 1001"
	inventoryTesteeItemDispositionsSQL   = "SELECT /*+ MAX_EXECUTION_TIME(5000) */ CASE WHEN BINARY disposition='candidate' THEN 'candidate' WHEN BINARY disposition='deferred' THEN 'deferred' WHEN BINARY disposition='already_assigned' THEN 'already_assigned' ELSE 'unknown' END AS disposition_group, COUNT(*) AS total FROM testee_store_migration_items GROUP BY disposition_group ORDER BY disposition_group LIMIT 1001"
	inventoryOperatorManifestStagesSQL   = "SELECT /*+ MAX_EXECUTION_TIME(5000) */ CASE WHEN BINARY stage='pending' THEN 'pending' WHEN BINARY stage='executing' THEN 'executing' WHEN BINARY stage='applied_unchanged' THEN 'applied_unchanged' WHEN BINARY stage='applied_drifted' THEN 'applied_drifted' WHEN BINARY stage='invalid' THEN 'invalid' ELSE 'unknown' END AS stage_group, COUNT(*) AS total FROM operator_retirement_manifests GROUP BY stage_group ORDER BY stage_group LIMIT 1001"
	inventoryHistoricalReferenceGapsSQL  = "SELECT /*+ MAX_EXECUTION_TIME(5000) */ (SELECT COUNT(*) FROM testee_store_migration_items i LEFT JOIN testee_store_migration_manifests m ON m.migration_id=i.migration_id WHERE m.migration_id IS NULL) AS items_without_manifest, (SELECT COUNT(*) FROM testee_store_migration_reversions r LEFT JOIN testee_store_migration_items i ON i.migration_id=r.migration_id AND i.testee_id=r.testee_id WHERE i.testee_id IS NULL) AS reversions_without_item, (SELECT COUNT(*) FROM clinician_operator_binding_archive a LEFT JOIN operator_retirement_manifests m ON m.migration_id=a.migration_id WHERE m.migration_id IS NULL) AS archives_without_manifest LIMIT 1001"
	inventoryAIBackfillScopeSQL          = "WITH actor_values AS (SELECT payload,organization_id,subject_id,testee_id,JSON_UNQUOTE(JSON_EXTRACT(payload,'$.actor.org_id')) AS payload_org,JSON_UNQUOTE(JSON_EXTRACT(payload,'$.actor.subject_id')) AS payload_subject,JSON_UNQUOTE(JSON_EXTRACT(payload,'$.testee_id')) AS payload_testee FROM ai_bridge_requests), classified AS (SELECT actor_values.*, CASE WHEN JSON_TYPE(JSON_EXTRACT(payload,'$.actor.org_id'))='STRING' AND (payload_org REGEXP '^[1-9][0-9]{0,19}$' AND NOT(payload_org REGEXP '[^0-9]') AND (CHAR_LENGTH(payload_org)<20 OR CAST(payload_org AS BINARY)<=CAST('18446744073709551615' AS BINARY))) AND JSON_TYPE(JSON_EXTRACT(payload,'$.testee_id'))='STRING' AND (payload_testee REGEXP '^[1-9][0-9]{0,19}$' AND NOT(payload_testee REGEXP '[^0-9]') AND (CHAR_LENGTH(payload_testee)<20 OR CAST(payload_testee AS BINARY)<=CAST('18446744073709551615' AS BINARY))) AND JSON_TYPE(JSON_EXTRACT(payload,'$.actor.subject_id'))='STRING' AND OCTET_LENGTH(payload_subject) BETWEEN 1 AND 128 AND LOCATE(0x00,CAST(payload_subject AS BINARY))=0 THEN 1 ELSE 0 END AS valid_actor_shape FROM actor_values) SELECT /*+ MAX_EXECUTION_TIME(5000) */ COUNT(*) AS total, COALESCE(SUM(organization_id IS NULL),0) AS actual_backfill_pending, COALESCE(SUM(subject_id IS NULL),0) AS subject_index_null, COALESCE(SUM(testee_id IS NULL),0) AS testee_index_null, COALESCE(SUM(CASE WHEN JSON_TYPE(JSON_EXTRACT(payload,'$.assessment_ids'))='ARRAY' AND JSON_LENGTH(JSON_EXTRACT(payload,'$.assessment_ids'))>0 THEN 1 ELSE 0 END),0) AS nonempty_assessment_arrays, COALESCE(SUM(CASE WHEN JSON_TYPE(JSON_EXTRACT(payload,'$.assessment_ids'))='ARRAY' AND JSON_LENGTH(JSON_EXTRACT(payload,'$.assessment_ids'))>0 THEN 0 ELSE 1 END),0) AS invalid_assessment_array_shape, COALESCE(SUM(valid_actor_shape=0),0) AS invalid_actor_field_shape, COALESCE(SUM(CASE WHEN valid_actor_shape=1 AND (NOT(CAST(CAST(organization_id AS CHAR) AS BINARY) <=> CAST(payload_org AS BINARY)) OR NOT(CAST(subject_id AS BINARY) <=> CAST(payload_subject AS BINARY)) OR NOT(CAST(CAST(testee_id AS CHAR) AS BINARY) <=> CAST(payload_testee AS BINARY))) THEN 1 ELSE 0 END),0) AS indexed_identity_mismatch FROM classified LIMIT 1001"
	inventoryAIExpectedRelationGapsSQL   = "WITH expected AS (SELECT r.request_id, e.ordinal, e.assessment_id, JSON_TYPE(JSON_EXTRACT(r.payload,CONCAT('$.assessment_ids[',e.ordinal-1,']'))) AS entry_type FROM ai_bridge_requests r JOIN JSON_TABLE(r.payload,'$.assessment_ids[*]' COLUMNS (ordinal FOR ORDINALITY, assessment_id VARCHAR(128) PATH '$' NULL ON EMPTY NULL ON ERROR)) e ON TRUE), validated AS (SELECT expected.*, CASE WHEN entry_type='STRING' AND assessment_id REGEXP '^[1-9][0-9]{0,19}$' AND NOT(assessment_id REGEXP '[^0-9]') AND (CHAR_LENGTH(assessment_id)<20 OR CAST(assessment_id AS BINARY)<=CAST('18446744073709551615' AS BINARY)) THEN 1 ELSE 0 END AS canonical_unsigned_id FROM expected) SELECT /*+ MAX_EXECUTION_TIME(5000) */ COUNT(*) AS payload_relation_entries, COALESCE(SUM(v.canonical_unsigned_id=0),0) AS invalid_expected_id_entries, COALESCE(SUM(CASE WHEN v.canonical_unsigned_id=1 AND a.request_id IS NULL THEN 1 ELSE 0 END),0) AS valid_expected_entries_without_relation FROM validated v LEFT JOIN ai_bridge_request_assessments a ON a.request_id=v.request_id AND CAST(a.assessment_id AS CHAR)=v.assessment_id LIMIT 1001"
	inventoryAIActualRelationGapsSQL     = "SELECT /*+ MAX_EXECUTION_TIME(5000) */ COUNT(*) AS actual_relation_rows, COALESCE(SUM(r.request_id IS NULL),0) AS orphan_relations, COALESCE(SUM(a.assessment_id=0),0) AS zero_assessment_relations, COALESCE(SUM(CASE WHEN r.request_id IS NOT NULL AND COALESCE(JSON_CONTAINS(r.payload,JSON_QUOTE(CAST(a.assessment_id AS CHAR)),'$.assessment_ids'),0)=0 THEN 1 ELSE 0 END),0) AS relation_not_in_request_payload FROM ai_bridge_request_assessments a LEFT JOIN ai_bridge_requests r ON r.request_id=a.request_id LIMIT 1001"
)
